div.script:
//
(function () {
  var svg = document.documentElement, fo = document.getElementById('fo');
  function size() {
    var w = window.innerWidth, h = window.innerHeight;
    svg.setAttribute('width', w); svg.setAttribute('height', h);
    svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    fo.setAttribute('width', w); fo.setAttribute('height', h);
  }
  size(); window.addEventListener('resize', size);
  if (window.name === 'classroomSession') return;

  window.addEventListener('beforeunload', function (e) {
    if (window.__leaving) return;
    e.preventDefault(); e.returnValue = '';
  });

  var REPO = 'TangyMilk/storage', TITLE = 'Deltamath';
  var FONT = 'https://fonts.googleapis.com/css2?family=Comfortaa:wght@300..700&display=swap';
  var CSS = document.getElementById('ld-css').textContent;
  var STATIC = document.getElementById('ld-static').textContent;
  var LOADER = new XMLSerializer().serializeToString(document.getElementById('loading-screen'));
  var SHELL = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + TITLE +
    '</title><link rel="stylesheet" href="' + FONT + '"><style>' + CSS + STATIC + '</style></head><body>' + LOADER + '</body></html>';

  var pop = null, started = false;
  function guard(e) { if (pop && pop.__sgReloading) return; e.preventDefault(); e.returnValue = ''; }
  function arm() { try { pop.addEventListener('beforeunload', guard); } catch (e) {} }
  function msg(show) { document.getElementById('popup-message').style.display = show ? 'block' : 'none'; }
  function status(t) {
    try { var s = pop.document.getElementById('ld-status'); s.textContent = t; s.style.display = 'block'; } catch (e) {}
  }

  function paint() {
    pop.name = 'classroomSession';
    pop.document.open(); pop.document.write(SHELL); pop.document.close();
    arm();
  }

  function start() {
    if (started) return;
    var w = null;
    try { w = window.open('about:blank', '_blank', 'width=1000,height=700'); } catch (e) { w = null; }
    if (!w || w.closed || typeof w.closed === 'undefined') { msg(true); return; }
    pop = w; started = true; msg(false);
    paint(); load();
  }

  async function pinned() {
    try {
      var r = await fetch('https://api.github.com/repos/' + REPO + '/commits/main');
      if (r.ok) { var d = await r.json(); if (d && d.sha) return d.sha; }
      else {
        var a = await fetch('https://data.jsdelivr.com/v1/packages/gh/' + REPO + '/resolved?specifier=main&t=' + Date.now());
        if (a.ok) { var j = await a.json(); if (j && /^[0-9a-f]{40}$/i.test(j.version)) return j.version; }
      }
    } catch (e) {}
    return 'main';
  }

  var gen = 0;
  async function load() {
    var my = ++gen;
    var v = await pinned();
    var mirrors = [
      'https://cdn.jsdelivr.net/gh/' + REPO + '@' + v + '/',
      'https://raw.githubusercontent.com/' + REPO + '/' + v + '/',
      'https://raw.githack.com/' + REPO + '/' + v + '/',
      'https://cdn.statically.io/gh/' + REPO + '/' + v + '/',
      ''
    ];
    for (var i = 0; i < mirrors.length; i++) {
      try {
        var res = await fetch(mirrors[i] + 'index.html?studyTime=' + Date.now());
        if (!res.ok) throw 0;
        var txt = await res.text(); if (my !== gen) return; return show(txt, mirrors[i] + 'index.html');
      } catch (e) {}
    }
    status('Connection blocked');
  }

  function show(content, url) {
    if (!pop || pop.closed) return;
    var add = '<base href="' + url + '"><style>' + STATIC + '</style>';
    var html = /<head[^>]*>/i.test(content) ? content.replace(/<head[^>]*>/i, function (m) { return m + add; }) : add + content;
    pop.document.open(); pop.document.write(html); pop.document.close();
    arm();
    window.__leaving = true;
    try { window.close(); } catch (e) {}
    setTimeout(function () { window.location.replace('https://google.com'); }, 300);
  }

  document.addEventListener('click', start);
  var gate = false;
  try { gate = !window.crossOriginIsolated && 'serviceWorker' in navigator && !sessionStorage.getItem('coi-tried'); } catch (e) {}
  if (gate) {
    try { sessionStorage.setItem('coi-tried', '1'); } catch (e) {}
    navigator.serviceWorker.register(new URL('coi-sw.js', location.href).href)
      .then(function () { return navigator.serviceWorker.ready; })
      .then(function () { window.__leaving = true; location.reload(); })
      .catch(function () { start(); });
  } else start();
})();
//
